<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {ArrowLeft,ArrowUpRight,Clock,GitBranch,BookOpen,Download,History,ChevronRight,Check,Compass} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import {playScene,canPlayAction,validatePlayWorld,validatePlayCheckpoint,type PlayWorld,type PlayCheckpoint,type PlayIntent} from './contract'
import {newPlayStep,savePlayableIntent,executePlayableIntent,discardPlayableIntent,playablePackage} from './operations'
import {playReadingCopy,saveReadingCopy} from '../catalog/reading-copy'
const router=useRouter()
const store=useLocal(),route=useRoute(),world=ref<Document<PlayWorld>|null>(null),head=ref<Document<PlayCheckpoint>|null>(null),preview=ref<Document<PlayCheckpoint>|null>(null),history=ref<Document<PlayCheckpoint>[]>([]),pending=ref<Document<PlayIntent>|null>(null),busy=ref(false),loaded=ref(false),error=ref(''),conflict=ref(false),historyOpen=ref(false),saveOpen=ref(false),missing=ref(false)
let disposed=false,loadEpoch=0,opening:ReturnType<typeof newPlayStep>|null=null,selection:{operation:string;value:PlayWorld;revision:number}|null=null
const current=computed(()=>preview.value||head.value),scene=computed(()=>world.value&&current.value?playScene(world.value.value.definition,current.value.value.state):null),past=computed(()=>!!preview.value&&preview.value.id!==head.value?.id),save=computed(()=>world.value?.value.saves.find(s=>s.id===world.value!.value.activeSaveId)),stateItems=computed(()=>world.value&&current.value?Object.entries(world.value.value.definition.items).map(([id,v])=>({id,label:v.label,value:current.value!.value.state.items[id]})):[]),known=computed(()=>world.value&&current.value?Object.entries(world.value.value.definition.flags).filter(([id])=>current.value!.value.state.flags[id]).map(([id,v])=>({id,label:v.label})):[])
function active(vault:typeof store.vault){return !disposed&&vault===store.vault&&!!vault?.unlocked}
async function load(){const vault=store.vault;if(!vault)return;const ticket=++loadEpoch;busy.value=true;try{const row=await vault.read<PlayWorld>(String(route.params.worldId));if(!active(vault)||ticket!==loadEpoch)return;if(!row||row.kind!=='world'){missing.value=true;world.value=null;return}validatePlayWorld(row.value,row.id);const slot=row.value.saves.find(s=>s.id===row.value.activeSaveId)!,cp=await vault.read<PlayCheckpoint>(slot.headId),journals=await vault.listPrefix<PlayIntent>('play-intent:');if(!cp||cp.kind!=='checkpoint')throw Error('存档的检查点缺失');validatePlayCheckpoint(cp.value,cp.id);const chain:Document<PlayCheckpoint>[]=[];let next:Document<PlayCheckpoint>|null=cp;const visited=new Set<string>();while(next&&chain.length<500){if(visited.has(next.id)||next.kind!=='checkpoint'||next.value.worldId!==row.id)throw Error('存档历史不完整');visited.add(next.id);chain.unshift(next);if(!next.value.parentId)break;next=await vault.read<PlayCheckpoint>(next.value.parentId)}if(!active(vault)||ticket!==loadEpoch)return;world.value=row;head.value=cp;history.value=chain;preview.value=null;pending.value=journals.filter(r=>r.value.type!=='create'&&r.value.worldId===row.id&&r.value.status==='ready').sort((a,b)=>a.updatedAt.localeCompare(b.updatedAt))[0]||null;opening=null;selection=null;missing.value=false;conflict.value=false}catch(e){if(active(vault)&&ticket===loadEpoch)error.value=(e as Error).message}finally{if(active(vault)&&ticket===loadEpoch){busy.value=false;loaded.value=true}}}
async function begin(actionId:string|null,fork=false){const vault=store.vault,row=world.value,cp=current.value;if(!vault||!row||!cp||busy.value||pending.value||opening||selection||!fork&&past.value)return;opening=newPlayStep(JSON.parse(canonical(row)),JSON.parse(canonical(cp)),actionId,fork);await run()}
async function run(){const vault=store.vault;if(!vault||busy.value||conflict.value)return;busy.value=true;error.value='';try{if(!pending.value){if(!opening)throw Error('请重新选择行动');pending.value=await savePlayableIntent(vault,opening.id,opening.value)}if(!active(vault))return;await executePlayableIntent(vault,pending.value);if(active(vault)){pending.value=null;opening=null;await load()}}catch(e){if(active(vault)){error.value=(e as Error).message;conflict.value=(e as {code?:string}).code==='REVISION_CONFLICT'}}finally{if(active(vault))busy.value=false}}
async function abandon(){const vault=store.vault,id=pending.value?.id||opening?.id;if(!vault||!id||busy.value)return;busy.value=true;try{const latest=await vault.read<PlayIntent>(id);if(latest?.value.status==='ready')await discardPlayableIntent(vault,latest);if(active(vault)){error.value='';opening=null;await load()}}catch(e){if(active(vault))error.value=(e as Error).message}finally{if(active(vault))busy.value=false}}
async function activate(id:string){const vault=store.vault,row=world.value;if(!vault||!row||busy.value||pending.value||opening||conflict.value)return;selection??={operation:'play-select:'+crypto.randomUUID(),revision:row.revision,value:{...JSON.parse(canonical(row.value)),activeSaveId:id}};busy.value=true;error.value='';try{await vault.commit(selection.operation,'world',row.id,selection.revision,selection.value);if(active(vault)){selection=null;saveOpen.value=false;await load()}}catch(e){if(active(vault)){error.value=(e as Error).message;conflict.value=(e as {code?:string}).code==='REVISION_CONFLICT'}}finally{if(active(vault))busy.value=false}}
function exportWork(){if(!world.value)return;const url=URL.createObjectURL(new Blob([playablePackage(world.value.value.definition)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=world.value.value.name+'.playable.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function saveJourney(){const vault=store.vault,row=world.value,point=current.value;if(!vault||!row||!point||busy.value||pending.value||opening||selection)return;busy.value=true;error.value='';try{const draft=await saveReadingCopy(vault,playReadingCopy(row,history.value,point.id));if(active(vault)){busy.value=false;await router.push({path:'/local/new-story',query:{draft:draft.id,copy:'1'}})}}catch(e){if(active(vault))error.value=(e as Error).message}finally{if(active(vault))busy.value=false}}
function see(cp:Document<PlayCheckpoint>){if(busy.value||pending.value||opening||selection)return;preview.value=cp.id===head.value?.id?null:cp;historyOpen.value=false;window.scrollTo({top:0,behavior:'instant'})}
function refresh(){if(!busy.value&&!pending.value&&!opening){error.value='';void load()}}
onBeforeRouteLeave(()=>{if(busy.value&&loaded.value)return false});onMounted(()=>void load());onUnmounted(()=>{disposed=true;loadEpoch++})
</script>
<template><section class="play-workspace" :class="'play-layout-'+(world?.value.definition.layout||'story')"><header class="play-toolbar"><RouterLink to="/local/library" aria-label="返回书架"><ArrowLeft :size="22"/></RouterLink><div><strong>{{world?.value.name||'文游'}}</strong><span>{{save?.name||'独立存档'}}</span></div><button aria-label="保存旅程为阅读稿" :disabled="!world||!current||busy||!!pending" @click="saveJourney"><BookOpen :size="20"/></button><button aria-label="导出文游作品" :disabled="!world||busy" @click="exportWork"><Download :size="20"/></button></header><p v-if="error" class="final-error play-error" role="alert">{{error}}</p><div v-if="!loaded" class="play-loading" role="status">正在打开存档…</div><div v-else-if="missing" class="final-empty"><Compass :size="32"/><h2>作品已删除或无法打开</h2><RouterLink to="/local/library">返回书架</RouterLink></div><template v-else-if="world&&current&&scene"><div class="play-story-grid"><aside class="play-inventory"><div class="play-state-time"><Clock :size="18"/><span>第 {{current.value.state.turn}} 步</span><small>{{current.value.state.minute}} 分钟</small></div><div v-if="stateItems.length" class="play-items"><span class="final-eyebrow">随身物品</span><div v-for="item in stateItems" :key="item.id"><span>{{item.label}}</span><strong>{{item.value}}</strong></div></div><div v-if="known.length" class="play-clues"><span class="final-eyebrow">已经发现</span><p v-for="clue in known" :key="clue.id"><Check :size="15"/>{{clue.label}}</p></div></aside><article class="play-story"><span class="play-scene-number">{{past?'检查点':scene.outcome==='success'?'旅程完成':scene.outcome==='failure'?'这次旅程已结束':'故事进行时'}}</span><h1>{{scene.title}}</h1><div class="play-prose" :class="{'play-dialogue-prose':world.value.definition.layout==='dialogue'}">{{current.value.text}}</div><div v-if="past" class="play-past"><span>第 {{current.value.state.turn}} 步 · 检查点</span><button :disabled="busy||!!pending||!!opening||!!selection||world.value.saves.length>=50" @click="begin(null,true)"><GitBranch :size="18"/>从这里新建存档</button><button :disabled="busy||!!pending||!!opening||!!selection" @click="preview=null">回到当前进度</button></div><div v-else-if="!pending&&!opening&&!selection" class="play-actions"><button v-for="action in scene.actions" :key="action.id" :disabled="busy||!canPlayAction(current.value.state,action)" @click="begin(action.id)"><span>{{action.label}}</span><small>{{action.cost}} 分钟</small><ChevronRight :size="18"/></button><button v-if="scene.outcome!=='continue'" :disabled="busy" @click="historyOpen=true"><History :size="18"/>看看走过的路</button></div><div v-if="pending||opening" class="play-recovery" role="status"><strong>{{busy?'正在保存这次行动…':conflict?'存档已有新进展':'这次行动等待保存'}}</strong><div><button class="final-primary" :disabled="busy||conflict" @click="run">{{busy?'保存中…':'重试保存行动'}}</button><button :disabled="busy" @click="abandon">{{conflict?'放弃旧行动并载入当前存档':'放弃待保存行动'}}</button></div></div><div v-if="selection" class="play-recovery"><button :disabled="busy||conflict" @click="activate(selection.value.activeSaveId)">重试切换存档</button><button :disabled="busy" @click="selection=null;refresh()">重新载入存档</button></div><button v-if="error&&!pending&&!opening&&!selection" :disabled="busy" @click="refresh">重新载入存档</button></article></div><footer class="play-controls"><button :disabled="busy||!!pending||!!opening||!!selection" :aria-expanded="historyOpen" @click="historyOpen=!historyOpen;saveOpen=false"><History :size="18"/>检查点</button><button :disabled="busy||!!pending||!!opening||!!selection" :aria-expanded="saveOpen" @click="saveOpen=!saveOpen;historyOpen=false"><BookOpen :size="18"/>存档<span>{{world.value.saves.length}}</span></button></footer><section v-if="historyOpen" class="play-drawer" aria-label="检查点历史"><header><h2>走过的路</h2><button aria-label="关闭检查点历史" @click="historyOpen=false">关闭</button></header><p v-if="history.length===500" class="final-subtle">最近 500 个检查点</p><button v-for="cp in history" :key="cp.id" :aria-current="cp.id===current.id?'step':undefined" @click="see(cp)"><span class="play-history-dot"></span><small>{{cp.value.state.turn.toString().padStart(2,'0')}}</small><span>{{playScene(world.value.definition,cp.value.state).title}}</span><ArrowUpRight :size="17"/></button></section><section v-if="saveOpen" class="play-drawer" aria-label="文游存档"><header><h2>独立存档</h2><button aria-label="关闭存档" @click="saveOpen=false">关闭</button></header><button v-for="slot in world.value.saves" :key="slot.id" :aria-current="slot.id===save?.id?'true':undefined" @click="activate(slot.id)"><BookOpen :size="18"/><span>{{slot.name}}</span><Check v-if="slot.id===save?.id" :size="18"/><ArrowUpRight v-else :size="17"/></button></section></template></section></template>
<style scoped>
.play-workspace{height:100dvh;background:var(--canvas);display:flex;flex-direction:column;overflow:hidden}.play-toolbar{display:grid;grid-template-columns:48px minmax(0,1fr) 48px;gap:16px;align-items:center;min-height:82px;padding:12px 28px;border-bottom:1px solid var(--edge);background:var(--panel);flex-shrink:0}.play-toolbar>a,.play-toolbar>button{display:grid;place-content:center;min-height:44px;min-width:44px;border-radius:12px}.play-toolbar>div{display:grid;gap:5px;text-align:center;min-width:0}.play-toolbar strong{font:18px var(--font-reading,serif);overflow-wrap:anywhere}.play-toolbar span{font-size:12px;color:var(--quiet)}.play-error{max-width:850px;margin:20px auto;padding:16px}.play-story-grid{display:grid;grid-template-columns:200px minmax(0,720px);max-width:1040px;width:100%;margin:0 auto;gap:60px;padding:60px 24px 28px;flex:1;min-height:0;overflow:auto}.play-inventory{color:var(--quiet);font-size:14px}.play-state-time{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:32px}.play-state-time small{width:100%;padding-left:26px}.play-items,.play-clues{display:grid;gap:12px;margin-bottom:32px}.play-items>div{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border:1px solid var(--edge);border-radius:12px;background:var(--panel)}.play-items strong{font-weight:500;color:var(--ink)}.play-clues p{display:flex;gap:8px;align-items:start;line-height:1.5;margin:0}.play-clues svg{flex-shrink:0;margin-top:3px;color:var(--accent)}.play-story{min-width:0}.play-scene-number{color:var(--accent);font-size:12px;letter-spacing:.16em}.play-story h1{font:38px var(--font-reading,serif);margin:18px 0 38px;color:var(--ink);line-height:1.45;overflow-wrap:anywhere}.play-prose{white-space:pre-wrap;overflow-wrap:anywhere;font:22px/2.15 var(--font-reading,serif);color:var(--ink)}.play-dialogue-prose{border-left:2px solid var(--accent);padding-left:24px}.play-actions{display:grid;gap:12px;margin-top:42px}.play-actions>button{display:flex;align-items:center;gap:12px;min-height:56px;text-align:left;border:1px solid var(--edge);border-radius:14px;background:var(--panel);color:var(--ink);padding:14px 18px}.play-actions>button:not(:disabled):hover{border-color:var(--accent);background:var(--wash)}.play-actions>button>span{flex:1}.play-actions small{font-size:12px;color:var(--quiet);white-space:nowrap}.play-actions>button:disabled{opacity:.42}.play-past{display:grid;gap:12px;margin-top:36px;border-top:1px solid var(--edge);padding-top:24px}.play-past>span{font-size:13px;color:var(--quiet)}.play-past button{display:flex;gap:8px;align-items:center;min-height:48px;justify-content:center;border:1px solid var(--edge);border-radius:12px}.play-recovery{padding:24px;background:var(--wash);border:1px solid var(--edge);border-radius:16px;margin-top:28px;display:grid;gap:16px}.play-recovery>div{display:flex;flex-wrap:wrap;gap:12px}.play-recovery button{min-height:48px;padding:12px}.play-recovery strong{font-weight:500}.play-controls{position:relative;display:flex;gap:6px;margin:16px auto max(18px,env(safe-area-inset-bottom));flex-shrink:0;border:1px solid var(--edge);border-radius:20px;background:var(--panel);padding:6px;box-shadow:0 8px 32px #162a2110;z-index:12}.play-controls button{display:flex;gap:8px;align-items:center;justify-content:center;min-height:48px;min-width:132px;padding:10px 14px;border-radius:14px;color:var(--accent)}.play-controls button:hover{background:var(--wash)}.play-controls span{font-size:12px}.play-drawer{position:fixed;bottom:96px;left:50%;transform:translateX(-50%);width:min(560px,calc(100% - 32px));max-height:60dvh;overflow:auto;background:var(--panel);padding:20px;border:1px solid var(--edge);border-radius:20px;box-shadow:0 12px 42px #162a2112;z-index:13}.play-drawer header{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}.play-drawer h2{font:24px var(--font-reading,serif);margin:0}.play-drawer header button{min-height:44px;min-width:48px}.play-drawer>button{position:relative;display:flex;align-items:center;gap:14px;width:100%;min-height:52px;padding:12px;border-radius:12px;text-align:left;overflow-wrap:anywhere}.play-drawer>button span:not(.play-history-dot){flex:1}.play-drawer>button[aria-current],.play-drawer>button:hover{background:var(--wash);color:var(--accent)}.play-drawer small{color:var(--quiet)}.play-history-dot{width:8px;height:8px;border-radius:50%;background:var(--accent);flex-shrink:0}.play-loading{text-align:center;color:var(--quiet);padding:80px 20px}.play-layout-investigation .play-items>div{border-style:dashed}@media(max-width:850px){.play-story-grid{grid-template-columns:1fr;gap:32px;max-width:740px;padding-top:32px}.play-inventory{display:flex;gap:18px;flex-wrap:wrap;border-bottom:1px solid var(--edge);padding-bottom:20px}.play-state-time{margin:0;min-width:130px}.play-items{display:flex;align-items:start;gap:10px;flex-wrap:wrap;margin:0}.play-items>.final-eyebrow{width:100%;font-size:10px}.play-items>div{gap:16px;padding:9px 12px}.play-clues{width:100%;margin:0;gap:8px}.play-clues p{font-size:12px}.play-story h1{font-size:32px;margin-bottom:26px}.play-prose{font-size:20px;line-height:2}.play-toolbar{padding:12px 16px;gap:8px}}@media(max-width:430px){.play-story-grid{padding:28px 22px}.play-prose{font-size:19px}.play-story h1{font-size:29px}.play-actions>button{padding:14px;gap:8px}.play-dialogue-prose{padding-left:16px}.play-toolbar strong{font-size:16px}.play-recovery{padding:18px}}
</style>
